FUNCTION_BLOCK MotorControl
VAR_INPUT
    StartBtn : BOOL;
    StopBtn  : BOOL;
    EStop    : BOOL;
END_VAR
VAR_OUTPUT
    Motor : BOOL;
END_VAR

(* Stop conditions have priority over a simultaneous start request. *)
IF StopBtn OR EStop THEN
    Motor := FALSE;
ELSIF StartBtn THEN
    Motor := TRUE;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK BlowerControl
VAR_INPUT
    DO_LOW              : BOOL;
    AERATION_E_STOP_NC  : BOOL;
END_VAR
VAR_OUTPUT
    BLOWER_RUN                  : BOOL;
    AERATION_BLOWER_CYCLE_COUNT : UINT;
END_VAR
VAR
    StartDelay : TON;
    PreviousRun : BOOL := FALSE;
END_VAR

(* The timer resets whenever demand is absent or the E-stop is active. *)
StartDelay(IN := DO_LOW AND AERATION_E_STOP_NC, PT := T#5s);

IF NOT DO_LOW OR NOT AERATION_E_STOP_NC THEN
    BLOWER_RUN := FALSE;
ELSE
    BLOWER_RUN := StartDelay.Q;
END_IF;

(* Count only the false-to-true transition of the run command. *)
IF BLOWER_RUN AND NOT PreviousRun THEN
    AERATION_BLOWER_CYCLE_COUNT := AERATION_BLOWER_CYCLE_COUNT + 1;
END_IF;
PreviousRun := BLOWER_RUN;
END_FUNCTION_BLOCK

FUNCTION_BLOCK EdgeDetection
VAR_INPUT
    value : DWORD;
END_VAR
VAR_OUTPUT
    hasChanged       : BOOL;
    hasRisingEdges   : BOOL;
    risingBits       : DWORD;
    noOfRisingBits   : USINT;
    hasFallingEdges  : BOOL;
    fallingBits      : DWORD;
    noOfFallingBits  : USINT;
END_VAR
VAR
    PreviousValue : DWORD := DWORD#0;
    BitIndex      : USINT;
    Mask          : DWORD;
END_VAR

risingBits := value AND NOT PreviousValue;
fallingBits := PreviousValue AND NOT value;
hasChanged := value <> PreviousValue;
hasRisingEdges := risingBits <> DWORD#0;
hasFallingEdges := fallingBits <> DWORD#0;

noOfRisingBits := 0;
noOfFallingBits := 0;
FOR BitIndex := 0 TO 31 DO
    Mask := SHL(DWORD#1, BitIndex);
    IF (risingBits AND Mask) <> DWORD#0 THEN
        noOfRisingBits := noOfRisingBits + 1;
    END_IF;
    IF (fallingBits AND Mask) <> DWORD#0 THEN
        noOfFallingBits := noOfFallingBits + 1;
    END_IF;
END_FOR;

PreviousValue := value;
END_FUNCTION_BLOCK

FUNCTION_BLOCK MovingAverage
VAR_INPUT
    cyclicExecution : BOOL;
    trigger         : BOOL;
    value           : LREAL;
    windowSize      : INT;
    reset           : BOOL;
END_VAR
VAR_OUTPUT
    average          : LREAL;
    windowSizeReached : BOOL;
    error            : BOOL;
    status           : WORD;
END_VAR
VAR
    Samples       : ARRAY[1..100] OF LREAL;
    SampleCount   : INT := 0;
    NextIndex     : INT := 1;
    RunningSum    : LREAL := 0.0;
    PreviousTrigger : BOOL := FALSE;
    TriggerRise   : BOOL;
    PreviousWindowSize : INT := 0;
    ShouldSample  : BOOL;
END_VAR

TriggerRise := trigger AND NOT PreviousTrigger;
PreviousTrigger := trigger;

IF (windowSize < 1) OR (windowSize > 100) THEN
    error := TRUE;
    status := WORD#16#8200;
    windowSizeReached := FALSE;
ELSIF reset THEN
    error := FALSE;
    status := WORD#16#0000;
    SampleCount := 0;
    NextIndex := 1;
    RunningSum := 0.0;
    average := 0.0;
    windowSizeReached := FALSE;
    PreviousWindowSize := windowSize;
ELSE
    error := FALSE;
    status := WORD#16#0000;

    (* A changed window starts a fresh averaging history. *)
    IF PreviousWindowSize <> windowSize THEN
        SampleCount := 0;
        NextIndex := 1;
        RunningSum := 0.0;
        average := 0.0;
        PreviousWindowSize := windowSize;
    END_IF;

    ShouldSample := cyclicExecution OR ((NOT cyclicExecution) AND TriggerRise);
    IF ShouldSample THEN
        IF SampleCount < windowSize THEN
            SampleCount := SampleCount + 1;
        ELSE
            RunningSum := RunningSum - Samples[NextIndex];
        END_IF;

        Samples[NextIndex] := value;
        RunningSum := RunningSum + value;
        NextIndex := NextIndex + 1;
        IF NextIndex > windowSize THEN
            NextIndex := 1;
        END_IF;

        average := RunningSum / INT_TO_LREAL(SampleCount);
    END_IF;

    windowSizeReached := SampleCount >= windowSize;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK IPv4Parser
VAR_INPUT
    ipText : STRING(254);
END_VAR
VAR_OUTPUT
    ipValue : UDINT;
END_VAR
VAR
    TextLength    : INT;
    Position      : INT;
    SegmentCount  : INT;
    SegmentLength : INT;
    SegmentValue  : UINT;
    DigitValue    : UINT;
    CharacterText : STRING(1);
    ParsedValue   : UDINT;
    Valid         : BOOL;
END_VAR

ipValue := UDINT#0;
TextLength := LEN(ipText);
SegmentCount := 0;
SegmentLength := 0;
SegmentValue := UINT#0;
ParsedValue := UDINT#0;
Valid := (TextLength > 0) AND (TextLength <= 15);

IF Valid THEN
    FOR Position := 1 TO TextLength DO
        (* MID extracts one character without string subscript access. *)
        CharacterText := MID(ipText, 1, Position);

        IF CharacterText = '.' THEN
            IF (SegmentLength = 0) OR (SegmentValue > UINT#255) THEN
                Valid := FALSE;
            ELSE
                SegmentCount := SegmentCount + 1;
                IF SegmentCount > 3 THEN
                    Valid := FALSE;
                ELSE
                    ParsedValue := (ParsedValue * UDINT#256) + UINT_TO_UDINT(SegmentValue);
                    SegmentLength := 0;
                    SegmentValue := UINT#0;
                END_IF;
            END_IF;
        ELSE
            IF CharacterText = '0' THEN
                DigitValue := UINT#0;
            ELSIF CharacterText = '1' THEN
                DigitValue := UINT#1;
            ELSIF CharacterText = '2' THEN
                DigitValue := UINT#2;
            ELSIF CharacterText = '3' THEN
                DigitValue := UINT#3;
            ELSIF CharacterText = '4' THEN
                DigitValue := UINT#4;
            ELSIF CharacterText = '5' THEN
                DigitValue := UINT#5;
            ELSIF CharacterText = '6' THEN
                DigitValue := UINT#6;
            ELSIF CharacterText = '7' THEN
                DigitValue := UINT#7;
            ELSIF CharacterText = '8' THEN
                DigitValue := UINT#8;
            ELSIF CharacterText = '9' THEN
                DigitValue := UINT#9;
            ELSE
                Valid := FALSE;
            END_IF;

            IF Valid THEN
                SegmentLength := SegmentLength + 1;
                SegmentValue := (SegmentValue * UINT#10) + DigitValue;
                IF SegmentValue > UINT#255 THEN
                    Valid := FALSE;
                END_IF;
            END_IF;
        END_IF;
    END_FOR;

    IF (SegmentLength = 0) OR (SegmentValue > UINT#255) THEN
        Valid := FALSE;
    ELSE
        SegmentCount := SegmentCount + 1;
        IF SegmentCount <> 4 THEN
            Valid := FALSE;
        ELSE
            ParsedValue := (ParsedValue * UDINT#256) + UINT_TO_UDINT(SegmentValue);
        END_IF;
    END_IF;
END_IF;

IF Valid THEN
    ipValue := ParsedValue;
ELSE
    ipValue := UDINT#0;
END_IF;
END_FUNCTION_BLOCK
